-- month-love-02
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"Месяц любви","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-love-02-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя личный план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly\">Открыть урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='42bc1762-9a13-5963-bdd5-3ea0e5f950a7';

-- month-love-03
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении здоровья органов грудной клетки и гармоничного проявления состояний анахаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении здоровья органов грудной клетки и гармоничного проявления состояний анахаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"Месяц любви","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-love-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении здоровья органов грудной клетки и гармоничного проявления состояний анахаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly\">Открыть урок 3</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='dce9025b-79f7-52bb-b59c-6878efbe78b9';

-- month-love-04
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве любви, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию четвёртой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве любви, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию четвёртой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"Месяц любви","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-love-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве любви, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию четвёртой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly\">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='b3506cf1-55c7-5f48-9e64-a4f63327b1cf';

-- month-love-05
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца любви. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца любви. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"Месяц любви","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-love-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Мы достигли середины Месяца любви. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре. А сейчас пришло время четвертого урока.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly\">Открыть урок 4</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='e4d17696-cfb3-5b07-8946-db525d9a2919';

-- month-love-06
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё дополнительный урок, направленный на гармонизацию четвёртой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё дополнительный урок, направленный на гармонизацию четвёртой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"Месяц любви","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-love-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>И ещё один сюрприз! Люблю радовать :)</p><p></p><p>Высылаю вам ещё дополнительный урок, направленный на гармонизацию четвёртой чакры.</p><p></p><p>Как и в прошлый раз - это запись утренней практики. Кстати, в Гармонизаторе тариф &quot;Мастер&quot; даёт доступ к 187 подобным урокам. То есть каждый день можно выполнять именно ту практику, которая наиболее соответствует вызовам этого дня. Гармонизатор определяет это в соответствии с планетными ритмами.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly\">Открыть доп. урок</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='8c6ef150-9141-5b93-a9a6-b9792090f84c';

-- month-love-07
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию анахаты, то есть на здоровье органов, расположенных в грудной клетке, а также психологическое и поведенческое оздоравливание сферы любви...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 5</a></p><p></p><p>И, так как месяц любви подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию пятой чакры - вишудхи - чакры творчества, высших ценностей, свободы, уникальности, артисцизма, волшебства и многих других прекрасных состояний. Ознакомиться с описанием следующего практикума вы можете на странице - <a href="https://zamkovoi.yoga/m5/">https://zamkovoi.yoga/m5/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png" alt="Месяц любви" width="504" height="119" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию анахаты, то есть на здоровье органов, расположенных в грудной клетке, а также психологическое и поведенческое оздоравливание сферы любви...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 5</a></p><p></p><p>И, так как месяц любви подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию пятой чакры - вишудхи - чакры творчества, высших ценностей, свободы, уникальности, артисцизма, волшебства и многих других прекрасных состояний. Ознакомиться с описанием следующего практикума вы можете на странице - <a href="https://zamkovoi.yoga/m5/">https://zamkovoi.yoga/m5/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-love-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-love/m4_email-6b6406763ee6.png","alt":"Месяц любви","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":125},{"id":"month-love-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию анахаты, то есть на здоровье органов, расположенных в грудной клетке, а также психологическое и поведенческое оздоравливание сферы любви...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly\">Открыть урок 5</a></p><p></p><p>И, так как месяц любви подходит к завершению, я хочу поблагодарить вас за совместные практики. Хотя, вы занимались по записям, в мире энергий всё соединено, и даже разделённость во времени не является препятствием. Надеюсь, данный месяц помог вам это почувствовать. И, если вы ощущаете как практики влияют на вашу жизнь, то я с удовольствием приглашаю вас присоединиться к практикам следующего месяца. Мы направим внимание на гармонизацию пятой чакры - вишудхи - чакры творчества, высших ценностей, свободы, уникальности, артисцизма, волшебства и многих других прекрасных состояний. Ознакомиться с описанием следующего практикума вы можете на странице - <a href=\"https://zamkovoi.yoga/m5/\">https://zamkovoi.yoga/m5/</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='b3fded35-19a8-5972-8e91-9b5e85e78d75';
